import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

/** Versioned SQL migrations generated by drizzle-kit (`packages/core/drizzle`). */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));

/**
 * Migration 0009 stopped on its own check: this Postgres has no pgvector.
 * The redacting logger writes an error's code and never its message, so
 * the code says it (docs/SELFHOST.md, "Upgrading to the memory").
 */
export class MissingExtensionError extends Error {
  override readonly name = "MissingExtensionError";
  readonly code = "pgvector_missing";
  constructor() {
    super("this Postgres has no pgvector extension; see docs/SELFHOST.md");
  }
}

/** Whether a failed migration is 0009's own check for pgvector (a RAISE, SQLSTATE P0001). */
export function isMissingPgvector(error: unknown): boolean {
  for (let current = error; current instanceof Error; current = (current as { cause?: unknown }).cause) {
    const code = (current as { code?: unknown }).code;
    if (code === "P0001" && current.message.includes("needs the pgvector extension")) return true;
  }
  return false;
}

export async function runMigrations(url: string, folder: string = MIGRATIONS_FOLDER): Promise<void> {
  const client = postgres(url, { max: 1, onnotice: () => undefined });
  try {
    await migrate(drizzle(client), { migrationsFolder: folder });
  } catch (error) {
    if (isMissingPgvector(error)) throw new MissingExtensionError();
    throw error;
  } finally {
    await client.end({ timeout: 5 });
  }
}
